import{z as o,x as s,o as A,c as d,q as l,j as t,D as e,d as n,s as r,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"行为公共政策与收束","description":"","frontmatter":{"title":"行为公共政策与收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bx-policy-map.md","filePath":"econ/bx-policy-map.md","lastUpdated":1791063341000}'),p={name:"econ/bx-policy-map.md"};function m(D,E,b,h,C,f){const B=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="行为公共政策与收束" tabindex="-1">行为公共政策与收束 <a class="header-anchor" href="#行为公共政策与收束" aria-label="Permalink to &quot;行为公共政策与收束&quot;">​</a></h1><div class="epigraph"><p>当偏好随参考点、期限与情境漂移，「尊重当事人自己的愿望」从公理变成待估问题——行为政策的第一道设计题不是工具，是福利判据。</p><footer>—— 据 Camerer, Issacharoff, Loewenstein, O&#39;Donoghue and Rabin, University of Pennsylvania Law Review, 2003；Thaler and Sunstein, Nudge, 2008 整理</footer></div><p><a href="/econ/bx-field-experiments">上一课</a>把随机化搬进真实决策的门口：默认与现时偏差在现场保住方向并放大量级，风险态度最不稳。本课程到此收束。回看路线：风险侧由<a href="/econ/bx-prospect-deep">前景理论的深化</a>给出 \\(\\lambda\\) 与累积加权；时间侧由<a href="/econ/bx-intertemporal-anomalies">跨期选择的异常</a>给出 \\(\\beta\\)–\\(\\delta\\) 与测量协议；社会侧由<a href="/econ/bx-social-preferences">社会偏好</a>给出 \\(\\alpha\\)、\\(\\beta\\) 与跨文化变异；<a href="/econ/bx-experiment-design">实验设计</a>给了防自欺的五步协议；<a href="/econ/bx-field-experiments">现场实验</a>给了谱系与换算表。收束课不引入新模型，只问五课参数上政策时最先撞上的那道题：判据。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统福利分析以显示偏好为判据：选择即福利。三课参数同时动摇它。现时偏差的人「想存」却拖到明天，两个自我各有显示偏好，选哪个？框架下翻转的选择没有唯一答案，损失厌恶使 WTP 与 WTA 分叉，消费者剩余不再单值；\\(\\alpha\\)、\\(\\beta\\) 的分布意味着「效率」的支付向量本身被公平重估。缺口于是先于工具：判据不定，任何助推都能被同时指控为解放与操纵——争论的从来不是证据，是「以谁的偏好为准」。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个判据口径，门槛递增。(1) 不对称家长制：只纠「对完全理性者无损、对偏差者有救」的错——冷静期、永远可以退出；它不依赖「哪种偏好才对」，争议最小，是行为政策的底线装置。(2) 自由家长制：判据「as judged by themselves」，以当事人的反思偏好为准；工具是不禁止选项、只改默认与架构——退休储蓄与器官捐献的默认即此。(3) 显示偏好的有限修复：给每个选择附一个「背景合理性」标记，只在被标记扭曲的场合否定显示偏好——它最接近标准福利经济学，工程上最难。证据标准横跨三个口径：干预上用 RCT 加预注册（上一课五步的重演），量级外推必过现场谱系，复制失败的工具退出工具箱。</p><p><span class="marginnote">术语翻译：「自由家长制」拆开读——家长制：设计者确实动了手脚（改默认）；自由：没人被禁止任何选项，随时可以反向退出。全部争议浓缩成一句话：被设计过的选择，还算不算「他自己的选择」。</span></p>',8)),(A(),t(i,null,{default:e(()=>[r(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAR%5B%22%E4%B8%89%E8%AF%BE%E5%8F%82%E6%95%B0%3A%20lambda%20%2F%20beta-delta%20%2F%20alpha-beta%22%5D%20--%3E%20WEL%5B%22%E5%88%A4%E6%8D%AE%3A%20%E6%98%BE%E7%A4%BA%E5%81%8F%E5%A5%BD%E5%8A%A8%E6%91%87%22%5D%0A%20%20WEL%20--%3E%20A%5B%22%E4%B8%8D%E5%AF%B9%E7%A7%B0%E5%AE%B6%E9%95%BF%E5%88%B6%3A%20%E7%90%86%E6%80%A7%E8%80%85%E6%97%A0%E6%8D%9F%22%5D%0A%20%20WEL%20--%3E%20B%5B%22%E8%87%AA%E7%94%B1%E5%AE%B6%E9%95%BF%E5%88%B6%3A%20%E5%8F%8D%E6%80%9D%E5%81%8F%E5%A5%BD%22%5D%0A%20%20WEL%20--%3E%20C%5B%22%E6%98%BE%E7%A4%BA%E5%81%8F%E5%A5%BD%E6%9C%89%E9%99%90%E4%BF%AE%E5%A4%8D%3A%20%E8%83%8C%E6%99%AF%E6%A0%87%E8%AE%B0%22%5D%0A%20%20A%20--%3E%20TOOL%5B%22%E5%B7%A5%E5%85%B7%E7%AE%B1%3A%20%E9%BB%98%E8%AE%A4%20%2F%20%E5%86%B7%E9%9D%99%E6%9C%9F%20%2F%20%E6%8A%AB%E9%9C%B2%20%2F%20%E6%83%A9%E7%BD%9A%E5%88%B6%E5%BA%A6%22%5D%0A%20%20B%20--%3E%20TOOL%0A%20%20C%20--%3E%20TOOL%0A%20%20TOOL%20--%3E%20EVID%5B%22RCT%20%E5%8A%A0%E9%A2%84%E6%B3%A8%E5%86%8C%2C%20%E7%8E%B0%E5%9C%BA%E9%87%8F%E7%BA%A7%2C%20%E5%A4%8D%E5%88%B6%E6%A3%80%E9%AA%8C%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[n("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"默认为什么是最强工具：它同时动两处——切换成本（架构）与参考点：放弃默认被编码为损失，权重 \\(\\lambda\\gt1\\)；第一课的 \\(\\lambda\\) 与上一课的现场量级在这里会合。同一逻辑给出它的边界：默认的量级依赖参考点人群，跨人群不可平移。判据与证据为什么不能互相替代：有判据无实验，好判据也配错量级——把学生问卷的 \\(\\beta\\) 直接代入政策弹性，会同时错方向与幅度；有实验无判据，RCT 只能告诉你「有效」，不能告诉你「该不该」。收束回地图：五课参数各挂一个政策端口——\\(\\lambda\\) 管默认与披露框架，\\(\\beta\\) 管自动储蓄与承诺制度，\\(\\alpha\\)、\\(\\beta\\)（社会侧）管惩罚制度与再分配的接受度，五步协议管证据质量，谱系表管外推折价。本课程的账：这套装备的产出是一张「参数—判据—工具」的对照表，不是一份直接施工的图纸。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"「as judged by themselves」自己留了口子：成瘾与冷热状态差的场合，冷状态的「自己」代言不了热状态——判据退回不对称家长制，只设冷静期，不替人选——三个口径门槛递增的用处正在于此：上层失灵退回下层。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"数字实例：Johnson–Goldstein 的跨国比较里，默认「同意捐献、可退出」的奥地利，有效同意率约 99%；默认「不同意、需登记」的邻国德国约 12%。两国文化相近，差得最远的几乎只是那道默认——这是「量级随架构走」最直观的一张对照。")],-1)),(A(),t(i,null,{default:e(()=>[r(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E9%BB%98%E8%AE%A4%3A%20%E8%87%AA%E5%8A%A8%E5%8A%A0%E5%85%A5%2C%20%E4%B8%8D%E6%83%B3%E8%A6%81%E5%86%8D%E9%80%80%E5%87%BA%22%5D%20--%3E%20COST%5B%22%E5%8A%A8%E7%AC%AC%E4%B8%80%E5%A4%84%3A%20%E6%8A%AC%E9%AB%98%E9%80%80%E5%87%BA%E8%A6%81%E5%8A%9E%E7%9A%84%E5%88%87%E6%8D%A2%E6%88%90%E6%9C%AC%22%5D%0A%20%20DEF%20--%3E%20REF%5B%22%E5%8A%A8%E7%AC%AC%E4%BA%8C%E5%A4%84%3A%20%E5%8F%82%E8%80%83%E7%82%B9%E8%90%BD%E5%9C%A8%E9%BB%98%E8%AE%A4%E4%B8%8A%22%5D%0A%20%20REF%20--%3E%20LOSS%5B%22%E9%80%80%E5%87%BA%20%3D%20%E6%94%BE%E5%BC%83%2C%20%E8%A2%AB%E7%BC%96%E7%A0%81%E4%B8%BA%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20LOSS%20--%3E%20LAM%5B%22%E4%B9%98%E4%B8%8A%20%CE%BB%20%E5%A4%A7%E4%BA%8E%201%20%E7%9A%84%E6%8D%9F%E5%A4%B1%E6%9D%83%E9%87%8D%22%5D%0A%20%20COST%20--%3E%20STAY%5B%22%E7%BB%9D%E5%A4%A7%E5%A4%9A%E6%95%B0%E4%BA%BA%E7%95%99%E5%9C%A8%E9%BB%98%E8%AE%A4%22%5D%0A%20%20LAM%20--%3E%20STAY%0A%20%20STAY%20--%3E%20BND%5B%22%E8%BE%B9%E7%95%8C%3A%20%E5%8F%82%E8%80%83%E7%82%B9%E4%BA%BA%E7%BE%A4%E4%B8%80%E6%8D%A2%2C%20%E9%87%8F%E7%BA%A7%E4%B8%8D%E5%8F%AF%E5%B9%B3%E7%A7%BB%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<p>这张图回答的是：默认为什么是最强工具，以及它的强度从哪来。它不是只给一个「省事起点」，而是同时动架构与参考点两处；第二处直接接到第一课的 \\(\\lambda\\)——这也预告了它的边界：参考点换了人群，量级就得重测。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程没有覆盖的三块：学习与信念更新、情绪与生理基础、行为参数的一般均衡反馈——补贴储蓄改变利率与资产价格时，局部参数不再是参数。行为政策的公信力系于复制：大规模推广中效应量缩水的工具要按证据标准退出，而不是按叙事留下——助推的大规模 meta 分析已见缩水。公平的福利地位本课刻意悬置：\\(\\alpha\\)、\\(\\beta\\) 说了人们在乎公平，没说政策应当在乎——那是规范经济学的题。后课默认：任何行为政策提案，先报判据口径与证据等级，再谈工具。</p><p><span class="marginnote">直觉类比：判据像量体，工具像剪刀。RCT 只能告诉你「剪得齐不齐」（有没有效果、多大），不能告诉你「该不该动这件衣裳」；不先量体就开剪，剪得再整齐也是白剪。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>显示偏好在三课参数下不再是充分统计：判据先于工具。</li><li>三个口径门槛递增：不对称家长制、自由家长制、显示偏好有限修复；上层失灵退回下层。</li><li>默认的强度来自切换成本加参考点的损失编码；量级随人群不可平移。</li><li>判据与证据不可互替：一个管该不该，一个管配多少。</li><li>工具箱按参数挂端口、按复制检验退出；产出是对照表，不是图纸。</li><li>出处：Camerer, Issacharoff, Loewenstein, O&#39;Donoghue and Rabin, <em>U. Penn. Law Review</em> 2003；Thaler and Sunstein, <em>Nudge</em> 2008；Bernheim and Rangel, <em>QJE</em> 2009；DellaVigna, <em>JEL</em> 2009。</li></ul>',6))])}const T=o(p,[["render",m]]);export{u as __pageData,T as default};
